"""Regenerates dashboard/defaults.js from the Python defaults (run after editing them)."""
import json, sys
from pathlib import Path
root = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(root))
from finder.prefilter import KEEP_WORDS, SKIP_URL_PARTS, SKIP_WORDS
from finder.remote import DEFAULTS
d = json.loads(json.dumps(DEFAULTS))
d["skip_words"] = SKIP_WORDS
d["keep_words"] = KEEP_WORDS
d["skip_url_parts"] = SKIP_URL_PARTS
(root / "dashboard" / "defaults.js").write_text(
    "// Generated by scripts/gen_defaults.py — mirrors finder/remote.py + finder/prefilter.py\n"
    "export const DEFAULTS = " + json.dumps(d, ensure_ascii=False, indent=2) + ";\n", encoding="utf-8")
print("ok")
